from .uc_data_transfer_base import UcDataTransferBase


class UcTcpProfile(UcDataTransferBase):

    def __init__(self, name, dt_definition, configuration, uc_connection, logger_name='ute_ue', test_name=None):
        """
        Init

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param uc_connection:
        :param logger_name:
        :param test_name:
        """
        super(UcTcpProfile, self).__init__(name, dt_definition, configuration, uc_connection, logger_name, test_name)

    def start(self):
        """
        Start data transfer
        :return:
        """
        if not self.existing_uc_test:
            self._create_new_test()
        self._start_and_wait_for_running()

    def _create_new_test(self):
        if self._dt_definition.protocol_details:
            self._validate_protocol_details(self._dt_definition.protocol_details)
            params = self._get_params_from_dt_definition()
        else:
            # Default params
            params = {"sequence": [{"type": "bytes", "value": 1000000}],
                      "updown": self._get_dt_direction(),
                      "randomManual": "manual"}
        if not self._dt_definition.is_forever_duration():
            params['duration'] = int(self._dt_definition.duration)
        self._uc_connection.new_test(name=self.test_name, test_type='TCP profile', test_params=params)
        self.logger.debug('Created new test {} type TCP profile with params {}'.format(self.test_name, params))

    def _validate_protocol_details(self, details):
        if details.get('randomManual', None) and \
                details.get('sequence', None):
            return
        raise ValueError('Invalid protocol details')

    def _get_params_from_dt_definition(self):
        details = self._dt_definition.protocol_details
        params = {'sequence': details['sequence'],
                  'updown': self._get_dt_direction(),
                  'randomManual': details['randomManual']}
        if not self._dt_definition.is_forever_duration():
            params['duration'] = int(self._dt_definition.duration)
        return params

    def _get_dt_direction(self):
        result = ''
        if self._dt_definition.direction == 'ul':
            result = 'upload'
        elif self._dt_definition.direction == 'dl':
            result = 'download'
        return result

    def get_average_throughput(self, omit=0):
        """
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()'
        if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        if omit:
            raise TypeError("UcTcpProfile: parameter 'omit' is currently not supported by ta_ue_plugin_ultracaller")
        response = self._uc_connection.get_test_result(test_id=self._test_id)
        return self._calculate_throughput(response['data'])

    @staticmethod
    def _calculate_throughput(results):
        throughput = []
        results.sort(key=lambda x: x['result']['timestamp'])
        for item in results:
            if item['phase'] == 'running':
                throughput.append(item['result']['throughput'])
        return round(sum(throughput) / float(len(throughput)), 0)
